export default function paidInvoice({body,eventId,channelId}) {
 if(!body||body.type!=='invoice.payment_succeeded'||body.id!==eventId||typeof eventId!=='string'||!eventId)throw Error('Invalid Stripe event');const x=body.data?.object;
 if(!x||!Number.isSafeInteger(x.amount_paid)||x.amount_paid<0||typeof x.currency!=='string'||!/^[A-Za-z]{3}$/.test(x.currency))throw Error('Invalid invoice amount or currency');if(typeof channelId!=='string'||!channelId.trim()||channelId==='YOUR_SLACK_CHANNEL_ID')throw Error('Configure Slack channel');
 const po=Array.isArray(x.custom_fields)&&typeof x.custom_fields[0]?.value==='string'?x.custom_fields[0].value.trim():'';const safe=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/[
]+/g,' ');const details='Amount (minor units): '+x.amount_paid+' '+x.currency.toUpperCase()+'
Customer: '+safe(x.customer_name)+'
Email: '+safe(x.customer_email)+'
Stripe event: '+safe(eventId);return{hasPo:!!po,filterGroups:[{filters:[{propertyName:'po_number',operator:'EQ',value:po}]}],channelId,paidText:':sparkles: An invoice has been paid :sparkles:
'+details+'
PO Number: '+safe(po),noPoText:':x: Stripe payment with no PO Number :x:
'+details,missingText:':x: Unable to find deal for the payment :x:
'+details+'
PO Number: '+safe(po)};
}

