export default function nextPaidDeal({results,paging,previousState,updatedRecord,slackTs}) {
 if(!Array.isArray(results)||results.length>100)throw Error('Invalid HubSpot search result');if(paging?.nextAfter)throw Error('More than 100 matching deals; inspect HubSpot before updating');const deals=[...results];for(const d of deals)if(!d||typeof d.id!=='string'||!d.id||typeof d.createdAt!=='string'||!Number.isFinite(Date.parse(d.createdAt)))throw Error('Invalid deal or creation date');deals.sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));if(new Set(deals.map(x=>x.id)).size!==deals.length)throw Error('Duplicate deal IDs');let phase='update',index=0;
 if(previousState!==null){if(!Number.isInteger(previousState.index)||previousState.index<0||previousState.index>=deals.length)throw Error('Invalid deal progress');if(previousState.phase==='update'){if(updatedRecord?.id!==deals[previousState.index].id)throw Error('Deal update not confirmed');}else if(previousState.phase==='notify'){if(typeof slackTs!=='string'||!slackTs)throw Error('Slack delivery not confirmed');}else throw Error('Invalid phase');phase=previousState.phase;index=previousState.index+1;if(index===deals.length){phase=phase==='update'?'notify':'done';index=0;}}
 if(!deals.length)phase='done';return{state:{phase,index},more:phase!=='done',updating:phase==='update',empty:deals.length===0,recordId:phase!=='done'?deals[index].id:'-'};
}
